use std::sync::{Arc, Weak};

let body = Arc::new(Payload::new());            // count in the allocation
let handle = Arc::clone(&body);                 // one atomic increment
let back: Weak<Payload> = Arc::downgrade(&body); // non-owning edge

// FFI: the foreign object owns the count, Rust owns the release call
struct GObject(*mut ffi::GObject);
impl Drop for GObject {
    fn drop(&mut self) { unsafe { ffi::g_object_unref(self.0) } }
}
